// Admins edit any schedule; a coach only the file named after their coach_id.
const p = $('Start').first().json;
const slugs = $input.all().map(i => i.json.name).filter(n => /\.json$/.test(n || '')).map(n => n.replace(/\.json$/, ''));
const allowed = p.role === 'admin' ? slugs : slugs.filter(s => s === p.coach_id);
const cfg = { site: 'https://unifight-haifa.github.io/unifight', raw: 'https://raw.githubusercontent.com/Unifight-haifa/unifight/main' };
return [{ json: { ...p, cfg, allowed,
  form_a: JSON.stringify([
    { fieldLabel: 'Расписание', fieldType: 'dropdown', requiredField: true, fieldOptions: { values: allowed.map(s => ({ option: s })) } },
    { fieldLabel: 'Что меняем', fieldType: 'radio', requiredField: true,
      fieldOptions: { values: ['Отмена', 'Перенос', 'Доп. тренировка', 'Объявление'].map(o => ({ option: o })) } },
  ]),
  denied: allowed.length ? '' : 'Нет расписания, которое вы можете менять. Расписание тренера меняет он сам или админ.',
} }];

const p = $('Allowed').first().json;
const a = $('Form A').last().json.data ?? $('Form A').last().json;
const sched = $('Get Schedule').last().json;
const venues = $('Get Venues').first().json;
const TYPES = { 'Отмена': 'cancel', 'Перенос': 'move', 'Доп. тренировка': 'extra', 'Объявление': 'note' };
const type = TYPES[a['Что меняем']];
const slug = a['Расписание'];
if (!type || !p.allowed.includes(slug)) return [];
const DAYS = ['Вс', 'Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб'];
const grades = g => !g ? '' : g[0] === 0 ? 'сад' : g[1] == null ? `${g[0]}+ кл.` : g[0] === g[1] ? `${g[0]} кл.` : `${g[0]}–${g[1]} кл.`;
const sessions = (sched.sessions || []).map((s, i) => {
  const kind = sched.kinds?.[s.kind]?.ru;
  const label = [`${DAYS[s.day]} ${s.start}–${s.end}`, venues[s.venue]?.ru || s.venue, grades(s.grades), kind, s.subgroup ? `гр. ${s.subgroup}` : '', sched.audiences?.[s.audience]?.ru]
    .filter(Boolean).join(' · ');
  const twin = sched.sessions.filter(o => o.day === s.day && o.start === s.start).length > 1;
  return { label: `${i + 1}. ${label}`, day: s.day, start: s.start, end: s.end, venue: s.venue, group: twin ? (s.audience || s.kind) : undefined };
});
const venueOpts = [...new Set(sched.sessions.map(s => s.venue))].map(v => venues[v]?.ru || v);
const sel = { fieldLabel: 'Тренировка', fieldType: 'dropdown', requiredField: type !== 'note',
  fieldOptions: { values: [...(type === 'note' ? [{ option: 'Всё расписание' }] : []), ...sessions.map(s => ({ option: s.label }))] } };
const date = (l, req = true) => ({ fieldLabel: l, fieldType: 'date', requiredField: req });
const text = (l, ph, req = false) => ({ fieldLabel: l, fieldType: 'text', placeholder: ph, requiredField: req });
const venue = req => ({ fieldLabel: 'Зал', fieldType: 'dropdown', requiredField: req, fieldOptions: { values: [...(req ? [] : [{ option: 'Тот же' }]), ...venueOpts.map(o => ({ option: o }))] } });
const note = req => ({ fieldLabel: 'Текст для сайта', fieldType: 'textarea', requiredField: req, placeholder: 'На своём языке. Переведу на иврит, русский и английский' });
const forms = {
  cancel: [sel, date('С'), date('По (пусто = один день)', false), note(true)],
  move: [sel, date('Дата, которая переносится'), date('Новая дата'), text('Начало', '17:30', true), text('Конец', '19:00', true), venue(false), note(true)],
  extra: [date('Дата'), text('Начало', '17:30', true), text('Конец', '19:00', true), venue(true), note(true)],
  note: [sel, date('С'), date('По'), note(true)],
};
return [{ json: { type, slug, sessions, venues, form_b: JSON.stringify(forms[type]) } }];

// Dates are Asia/Jerusalem calendar days; the site hides the change outside [from, to].
const s = $('Sessions').last().json;
const p = $('Allowed').first().json;
const b = $input.first().json.data ?? $input.first().json;
const errors = [];
const D = v => { const x = String(v || '').slice(0, 10); return /^\d{4}-\d{2}-\d{2}$/.test(x) ? x : ''; };
const T = v => { const x = String(v || '').trim().replace('.', ':'); return /^([01]?\d|2[0-3]):[0-5]\d$/.test(x) ? x.padStart(5, '0') : ''; };
const wd = d => new Date(`${d}T12:00:00Z`).getUTCDay();
const today = new Date().toLocaleDateString('sv-SE', { timeZone: 'Asia/Jerusalem' });
const pick = s.sessions.find(x => x.label === b['Тренировка']);
const venueId = name => Object.keys(s.venues).find(k => s.venues[k].ru === name) || '';
const ch = { schedule: s.slug, type: s.type };
const sess = x => ({ day: x.day, start: x.start, ...(x.group ? { group: x.group } : {}) });
if (s.type === 'cancel') {
  ch.from = D(b['С']); ch.to = D(b['По (пусто = один день)']) || ch.from;
  if (!pick) errors.push('выберите тренировку');
  else {
    ch.session = sess(pick);
    // The site rejects a cancel whose window has no day matching the class weekday.
    const days = ch.from && ch.to ? Math.round((Date.parse(ch.to) - Date.parse(ch.from)) / 864e5) : -1;
    if (days >= 0 && ![...Array(Math.min(days + 1, 7)).keys()].some(i => (wd(ch.from) + i) % 7 === pick.day)) errors.push('в эти даты нет такой тренировки');
  }
} else if (s.type === 'move') {
  ch.from = ch.to = D(b['Дата, которая переносится']);
  if (!pick) errors.push('выберите тренировку');
  else { ch.session = sess(pick); if (ch.from && wd(ch.from) !== pick.day) errors.push('дата не совпадает с днём недели тренировки'); }
  ch.new = { date: D(b['Новая дата']), start: T(b['Начало']), end: T(b['Конец']),
    venue: b['Зал'] && b['Зал'] !== 'Тот же' ? venueId(b['Зал']) : (pick?.venue || '') };
} else if (s.type === 'extra') {
  ch.new = { date: D(b['Дата']), start: T(b['Начало']), end: T(b['Конец']), venue: venueId(b['Зал']) };
  ch.from = ch.to = ch.new.date;
} else {
  ch.from = D(b['С']); ch.to = D(b['По']);
  if (pick) ch.session = sess(pick);
}
if (!ch.from || !ch.to) errors.push('нужны даты');
else if (ch.to < ch.from) errors.push('«по» раньше, чем «с»');
else if (ch.to < today) errors.push('даты уже прошли');
if (ch.new) {
  if (!ch.new.date || !ch.new.start || !ch.new.end) errors.push('новая дата и время в формате ЧЧ:ММ');
  else if (ch.new.end <= ch.new.start) errors.push('конец раньше начала');
  else if (wd(ch.new.date) === 6) errors.push('в субботу тренировок нет');
  if (!ch.new.venue) errors.push('выберите зал');
}
const noteSrc = String(b['Текст для сайта'] || '').trim();
if (!noteSrc) errors.push('нужен текст для сайта');
return [{ json: { ok: !errors.length, errors, change: ch, note_src: noteSrc, author: p.coach_id,
  context: 'one-off training schedule change shown on the club website', fields: { note: noteSrc }, limits: { note: 300 } } }];

const c = $('Build Change').last().json;
const p = $('Allowed').first().json;
let note = null;
if (c.note_src) {
  const t = $('Translate Note').last().json.tr;
  note = { he: t.he.note, ru: t.ru.note, en: t.en.note };
}
const ch = c.change;
const id = `${ch.from}-${ch.schedule}-${ch.type}-${Math.random().toString(36).slice(2, 6)}`;
const file = { id, schedule: ch.schedule, type: ch.type, from: ch.from, to: ch.to,
  ...(ch.session ? { session: ch.session } : {}), ...(ch.new ? { new: ch.new } : {}), ...(note ? { note } : {}),
  author: c.author, created: new Date().toISOString() };
const TYPE_RU = { cancel: 'Отмена', move: 'Перенос', extra: 'Дополнительная тренировка', note: 'Объявление' };
const s = $('Sessions').last().json;
const sessLabel = ch.session ? (s.sessions.find(x => x.day === ch.session.day && x.start === ch.session.start)?.label || '') : '';
const preview = [
  `${TYPE_RU[ch.type]} · ${ch.schedule}`, `На сайте: ${ch.from}${ch.to !== ch.from ? ' … ' + ch.to : ''}, потом расписание вернётся к обычному.`,
  sessLabel ? `Тренировка: ${sessLabel}` : '',
  ch.new ? `Новое: ${ch.new.date} ${ch.new.start}–${ch.new.end}, ${s.venues[ch.new.venue]?.ru || ch.new.venue}` : '',
  note ? `\nHE: ${note.he}\nRU: ${note.ru}\nEN: ${note.en}` : '',
  ...(c.note_src && $('Translate Note').last().json.warnings.length ? ['Проверьте: ' + $('Translate Note').last().json.warnings.join('; ')] : []),
].filter(Boolean).join('\n');
return [{ json: { file, preview, chat_id: p.chat_id,
  commit: { files: [{ path: `content/schedule-changes/${id}.json`, content: JSON.stringify(file, null, 1) + '\n' }],
    message: `Schedule: ${ch.type} ${ch.schedule} ${ch.from}${ch.to !== ch.from ? '..' + ch.to : ''}\n\nBy ${c.author} via telegram`,
    live_url: `${p.cfg.site}/schedule-changes.json`, live_match: `"${id}"` } } }];

const f = $('Final Change').first().json;
const r = $input.first().json;
const text = r.live
  ? `Изменение на сайте (${f.file.from}${f.file.to !== f.file.from ? ' … ' + f.file.to : ''}). После этих дат расписание вернётся само.`
  : `Изменение сохранено (коммит ${String(r.sha).slice(0, 7)}), но на сайте пока не видно. Проверьте через несколько минут.`;
return [{ json: { chat_id: f.chat_id, text, notify_admin: !r.live } }];

// news-publish takes the post in one language and does translation, preview, commit and social posting itself.
const f = $('Final Change').first().json.file;
const p = $('Allowed').first().json;
const s = $('Sessions').last().json;
const lang = f.note ? ($('Translate Note').last().json.src_lang || 'ru') : (['he', 'ru', 'en'].includes(p.lang) ? p.lang : 'ru');
const fmt = d => d.split('-').reverse().slice(0, 2).join('.');
const span = f.to !== f.from ? `${fmt(f.from)}–${fmt(f.to)}` : fmt(f.from);
const sess = f.session ? `${s.sessions.find(x => x.day === f.session.day && x.start === f.session.start)?.label.replace(/^\d+\.\s*/, '') || ''}` : '';
const T = {
  ru: { cancel: `Отмена тренировки ${span}`, move: `Перенос тренировки ${span}`, extra: `Дополнительная тренировка ${span}`, note: `Расписание: ${span}` },
  he: { cancel: `ביטול אימון ${span}`, move: `שינוי מועד אימון ${span}`, extra: `אימון נוסף ${span}`, note: `מערכת אימונים: ${span}` },
  en: { cancel: `Training cancelled ${span}`, move: `Training moved ${span}`, extra: `Extra training ${span}`, note: `Schedule update ${span}` },
};
const moved = f.new ? `${fmt(f.new.date)} ${f.new.start}–${f.new.end}, ${s.venues[f.new.venue]?.[lang] || f.new.venue}` : '';
const body = [f.note?.[lang], sess, moved].filter(Boolean).join('\n\n');
return [{ json: {
  channel: 'telegram', chat_id: p.chat_id, email: '', author_id: p.coach_id, author_name: p.name,
  src_lang: lang, title: T[lang][f.type], body: body.length >= 20 ? body : `${body}\n\n${p.cfg.site}/${lang}/`.trim(),
  cover_alt: '', tags: ['schedule'], draft_id: `sched-${f.id}`,
}, binary: $input.first().binary }];
